def strip():
 return '<section class="daily-services" aria-label="Praktische informatie"><span>Handig vandaag</span>'+''.join('<a href="'+url+'"><b>'+label+'</b><span>'+sub+'</span><i aria-hidden="true">›</i></a>' for label,sub,url in SERVICES)+'</section>'
